<?php require '../includes/functions.php';$u=require_role('department_admin');verify_csrf();$pdo=db();$id=(int)($_GET['id']??$_POST['id']??0);$q=$pdo->prepare('SELECT g.*,u.full_name citizen,u.email FROM grievances g JOIN users u ON u.id=g.citizen_id WHERE g.id=? AND g.department_id=?');$q->execute([$id,$u['department_id']]);$g=$q->fetch();if(!$g){http_response_code(404);exit('Grievance not found.');}$allowed=['Under Review','Assigned','In Progress','Resolved','Closed','Rejected','Reopened'];if($_SERVER['REQUEST_METHOD']==='POST'){$status=$_POST['status']??'';$remarks=trim($_POST['remarks']??'');$due=$_POST['expected_resolution_date']?:null;$resolution=trim($_POST['resolution_details']??'');$reject=trim($_POST['rejection_reason']??'');$public=isset($_POST['public_update']);if(!in_array($status,$allowed,true))$error='Choose a valid status.';elseif(($status==='Rejected'&&$reject==='')||($status==='Resolved'&&$resolution===''))$error='A rejection reason or resolution details are required for that status.';else{$pdo->beginTransaction();try{$q=$pdo->prepare('UPDATE grievances SET status=?,expected_resolution_date=?,resolution_details=?,rejection_reason=? WHERE id=? AND department_id=?');$q->execute([$status,$due,$resolution?:null,$reject?:null,$id,$u['department_id']]);record_history($pdo,$id,$g['status'],$status,$u['id'],$remarks?:($resolution?:$reject),$public);$q=$pdo->prepare('INSERT INTO notifications(user_id,grievance_id,message) VALUES(?,?,?)');$q->execute([$g['citizen_id'],$id,'Your grievance '.$g['tracking_number'].' is now '.$status.'.']);$pdo->commit();flash('Grievance updated.');redirect('department/view.php?id='.$id);}catch(Throwable $e){$pdo->rollBack();$error='Could not update grievance.';}}$q=$pdo->prepare('SELECT * FROM grievances WHERE id=?');$q->execute([$id]);$g=$q->fetch();}$q=$pdo->prepare('SELECT h.*,u.full_name FROM grievance_history h JOIN users u ON u.id=h.updated_by WHERE grievance_id=? ORDER BY created_at DESC');$q->execute([$id]);$hist=$q->fetchAll();$q=$pdo->prepare('SELECT id,full_name FROM users WHERE role_id=(SELECT id FROM roles WHERE name="department_admin") AND department_id=? AND is_active=1');$q->execute([$u['department_id']]);$officers=$q->fetchAll();$pageTitle='Process grievance';require '../includes/header.php';?><h1><?=e($g['tracking_number'])?>: <?=e($g['title'])?></h1><section class="panel"><p><b>Citizen:</b> <?=e($g['citizen'])?> · <?=e($g['email'])?></p><p><b>Location:</b> <?=e($g['location'])?></p><p><?=nl2br(e($g['description']))?></p><a href="<?=e(url('public/download.php?id='.$id))?>">Download attachment</a></section><?php if(!empty($error)):?><p class="error"><?=e($error)?></p><?php endif?><section class="panel form-narrow"><h2>Update processing</h2><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Status</label><select name="status" required><?php foreach($allowed as $st):?><option <?= $g['status']===$st?'selected':''?>><?=e($st)?></option><?php endforeach?></select><label>Expected resolution date</label><input type="date" name="expected_resolution_date" value="<?=e($g['expected_resolution_date'])?>"><label>Public remarks</label><textarea name="remarks"><?=e($_POST['remarks']??'')?></textarea><label>Resolution details (required when resolved)</label><textarea name="resolution_details"><?=e($g['resolution_details'])?></textarea><label>Rejection reason (required when rejected)</label><textarea name="rejection_reason"><?=e($g['rejection_reason'])?></textarea><label><input type="checkbox" name="public_update" checked style="width:auto"> Show remarks in citizen history</label><button>Save update</button></form></section><section class="panel"><h2>History</h2><?php foreach($hist as $h):?><article class="card"><b><?=e($h['new_status'])?></b> — <?=e($h['created_at'])?><p><?=e($h['remarks'])?></p><small><?= $h['is_public']?'Public update':'Internal note'?></small></article><?php endforeach?></section><?php require '../includes/footer.php';?>
